code.Java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextDouble()) {
            double r = sc.nextDouble();
            System.out.printf("%.2f\n", 3.14 * r * r);
        }
    }
}

